// --- CONFIGURATION ---
u_min := 0;
u_max := 6.28318; // 2*PI
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- SHADER CODE ---
// NB: do not declare variables named PI, pi, tau: the translator
// replaces them with the numeric value throughout the script.

// Geometric parameters
float a = 3.0;  // Four-leaf clover amplitude
float r = 0.25; // Tube radius

// Curve: four-leaf clover (polar rose rho = a*cos(2*theta)) in the
// z=0 plane. It passes through the origin FOUR times (u = 0.7854 + k*1.5708):
// there the four branches cross and the tube self-intersects.
// NB: opposite branches (k and k+2) reach the origin TANGENT to the
// same line (y=x or y=-x), so the merging of the arms at the
// center is more extended than in the lemniscate (with these parameters
// it reaches radius ~1.24): it is real geometry, not an artifact.
float c2u = cos(2.0 * u);
float s2u = sin(2.0 * u);
vec3 Curve = vec3(a * c2u * cos(u), a * c2u * sin(u), 0.0);

// --- FIRST DERIVATIVE (analytic velocity) ---
vec3 dC = vec3(
    -2.0 * a * s2u * cos(u) - a * c2u * sin(u),
    -2.0 * a * s2u * sin(u) + a * c2u * cos(u),
    0.0
);

vec3 Tangent = normalize(dC);

// --- STABLE FRAME COMPUTATION ---
// The curve lies in the z=0 plane: the tangent is never parallel
// to Z, so the frame never degenerates.
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = normalize(cross(Tangent, Up));
vec3 Norm = normalize(cross(Binorm, Tangent));

// --- TUBE CONSTRUCTION ---
vec3 pos = Curve + r * (cos(v) * Norm + sin(v) * Binorm);

// Return the point in 4D (X, Y, Z, P)
return vec4(pos * 0.35, 0.0);

//CUTOUT_BEGIN
// Cut of the inner walls in the crossing zone (origin).
// Scheme inherited from the Self-Intersecting Tube (lemniscate): PRECISE
// distance with coarse scan + 5 Newton steps — the raw
// samples alone estimate the minimum with error ~1e-2 and produce
// z-fight patches and jagged edges along the seam.
// Difference: the nodes here are FOUR (u_k = 0.7854 + k*1.5708,
// all at the origin) and for a fragment near node k the
// branches of the other THREE nodes are checked. Its own branch cannot
// touch itself (verified numerically: stays at distance >= 0.55 with
// r = 0.25), so it is skipped.
float a2 = 3.0;
float r2 = 0.25;
float PI_2 = 3.14159265359;

// node closest to the fragment (in parameter, wrapped on 2*PI)
float uw = u - PI_2 * 2.0 * floor(u / (PI_2 * 2.0));
float kNear = floor((uw - PI_2 * 0.25) / (PI_2 * 0.5) + 0.5);
float uNode = PI_2 * 0.25 + kNear * PI_2 * 0.5;

float activateWindow = 0.5;
bool didCut = false;

if (abs(uw - uNode) < activateWindow) {
    float c2f = cos(2.0 * u);
    float s2f = sin(2.0 * u);
    vec3 Curve2 = vec3(a2 * c2f * cos(u), a2 * c2f * sin(u), 0.0);
    vec3 dC2 = vec3(
        -2.0 * a2 * s2f * cos(u) - a2 * c2f * sin(u),
        -2.0 * a2 * s2f * sin(u) + a2 * c2f * cos(u),
        0.0
    );
    vec3 Tangent2 = normalize(dC2);
    vec3 Up2 = vec3(0.0, 0.0, 1.0);
    vec3 Binorm2 = normalize(cross(Tangent2, Up2));
    vec3 Norm2 = normalize(cross(Binorm2, Tangent2));
    vec3 pos2 = Curve2 + r2 * (cos(v) * Norm2 + sin(v) * Binorm2);

    float bestDist = 1000.0;

    for (float j = 0.0; j < 4.0; j = j + 1.0) {
        float node = PI_2 * 0.25 + j * PI_2 * 0.5;
        // skip the fragment's node (equivalence mod 2*PI)
        float dn = abs(node - uNode);
        dn = min(dn, PI_2 * 2.0 - dn);
        if (dn < 0.1) { continue; }

        // 1. coarse scan around the node
        float bestU = node;
        float bestD = 1000.0;
        for (float k = 0.0; k < 16.0; k = k + 1.0) {
            float u2 = node - 0.4 + 0.8 * (k / 15.0);
            float cc = cos(2.0 * u2);
            vec3 c2 = vec3(a2 * cc * cos(u2), a2 * cc * sin(u2), 0.0);
            float d = length(pos2 - c2);
            if (d < bestD) { bestD = d; bestU = u2; }
        }

        // 2. Newton on g(u2) = dot(pos2 - C(u2), C'(u2)) = 0
        float uN = bestU;
        for (float it = 0.0; it < 5.0; it = it + 1.0) {
            float cN2 = cos(2.0 * uN);
            float sN2 = sin(2.0 * uN);
            float cN1 = cos(uN);
            float sN1 = sin(uN);
            vec3 cN = vec3(a2 * cN2 * cN1, a2 * cN2 * sN1, 0.0);
            vec3 t1 = vec3(-2.0 * a2 * sN2 * cN1 - a2 * cN2 * sN1,
                           -2.0 * a2 * sN2 * sN1 + a2 * cN2 * cN1, 0.0);
            vec3 t2 = vec3(a2 * (-5.0 * cN2 * cN1 + 4.0 * sN2 * sN1),
                           a2 * (-5.0 * cN2 * sN1 - 4.0 * sN2 * cN1), 0.0);
            vec3 w = pos2 - cN;
            float g = dot(w, t1);
            float gp = dot(w, t2) - dot(t1, t1);
            if (abs(gp) > 0.000001) { uN = uN - g / gp; }
            uN = clamp(uN, node - 0.45, node + 0.45);
        }
        float cB2 = cos(2.0 * uN);
        vec3 cB = vec3(a2 * cB2 * cos(uN), a2 * cB2 * sin(uN), 0.0);
        bestDist = min(bestDist, min(bestD, length(pos2 - cB)));
    }

    didCut = (bestDist < r2);
}

return didCut;
//CUTOUT_END
